import{_ as s,o as t,c as a,ag as i}from"./chunks/framework.jVX1Yi1C.js";const k=JSON.parse('{"title":"Typical use","description":"","frontmatter":{},"headers":[],"relativePath":"daily-use.md","filePath":"daily-use.md"}'),n={name:"daily-use.md"};function o(h,e,l,r,d,c){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="typical-use" tabindex="-1">Typical use <a class="header-anchor" href="#typical-use" aria-label="Permalink to &quot;Typical use&quot;">​</a></h1><p>This page describes the work that comes back again and again after the setup. The <a href="./tutorial">tutorial</a> shows the first time of most of it, step by step; this page is the reference. <a href="./harness-command">harness-command.md</a> describes the contract of every verb: a verb that changes something prints its plan, and <code>--apply</code> makes the change.</p><h2 id="change-an-agent-a-skill-a-rule-or-an-instruction" tabindex="-1">Change an agent, a skill, a rule or an instruction <a class="header-anchor" href="#change-an-agent-a-skill-a-rule-or-an-instruction" aria-label="Permalink to &quot;Change an agent, a skill, a rule or an instruction&quot;">​</a></h2><p>Edit the source in this repository, never its installed copy in <code>~/.claude/</code>. The sources are in the neutral directories <code>agents/</code>, <code>skills/</code>, <code>rules/</code>, <code>instructions/</code> and <code>commands/</code>, and in <code>adapters/claude/</code> for <code>CLAUDE.md</code> and <code>RTK.md</code>. A fact about your own research tree goes into the <a href="./concepts#tree-instructions">tree instructions</a>. The next <code>harness install --apply</code> overwrites an edit of an installed copy, and the installed settings refuse such an edit from a <a href="./concepts#session">session</a>.</p><p>Then read the plan and <a href="./concepts#install">install</a> the change:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span></span></code></pre></div><p>A running session keeps the files that it has read. After an <code>--apply</code>, the verb prints one line for each <a href="./concepts#frontend">frontend</a> whose files changed, which tells you to restart that frontend.</p><p><strong>Put a correction into a file.</strong> A fact that you tell a session lasts for that session only. A fact in an <a href="./concepts#instruction-file">instruction file</a>, a <a href="./concepts#rule">rule</a>, a <a href="./concepts#skill">skill</a> or the tree instructions reaches every later session. Step 8 of the tutorial, <a href="./tutorial#step-8-make-a-correction-that-lasts">Make a correction that lasts</a>, shows it once from the start to the end.</p><h2 id="change-the-settings" tabindex="-1">Change the settings <a class="header-anchor" href="#change-the-settings" aria-label="Permalink to &quot;Change the settings&quot;">​</a></h2><p>The settings template <code>settings/settings.proposal.json</code> is the source of the sections <code>permissions</code>, <code>hooks</code> and <code>sandbox</code> of <code>~/.claude/settings.json</code>. Edit the template, then read the difference and install it, in your own terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> settings</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> settings</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span></span></code></pre></div><p>A grant that names you, your institution or your machine goes into the <a href="./concepts#profile">profile</a>, not into the template. Commit the template when you install a change: the commit is the record of the installed sections. To undo a change, install the template of an earlier commit with <code>--proposal</code>. Run these two commands in the checkout:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HEAD~1:settings/settings.proposal.json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/previous.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> settings</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --proposal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/previous.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span></span></code></pre></div><p><a href="./security#check-a-change-of-the-settings">security.md</a> says how to check the result.</p><h2 id="the-drift-warning-at-session-start" tabindex="-1">The drift warning at session start <a class="header-anchor" href="#the-drift-warning-at-session-start" aria-label="Permalink to &quot;The drift warning at session start&quot;">​</a></h2><p><code>harness install --apply</code> writes the stamp <code>~/.claude/.harness-install.json</code>. At each session start, the <code>SessionStart</code> <a href="./concepts#hook">hook</a> <code>hooks/install-drift.py</code> computes the stamp&#39;s digest again from the sources. It warns when the installed layer is behind its sources, when the stamp is missing, and when it cannot read a source or the stamp. The warning names the cause and the command.</p><p>When the warning appears, an edit of a source is not installed yet. Run the dry run, read the plan, and apply it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span></span></code></pre></div><p>The hook only warns. It blocks nothing, and the session continues with the old installed layer. <a href="./architecture#the-claude-code-layer">architecture.md</a> describes the stamp.</p><h2 id="the-leak-check-before-a-push" tabindex="-1">The leak check before a push <a class="header-anchor" href="#the-leak-check-before-a-push" aria-label="Permalink to &quot;The leak check before a push&quot;">​</a></h2><p>The pre-push hook of this repository runs two leak checks before a push to <code>main</code>: gitleaks finds secrets and home paths, and <code>harness leaks --commits</code> finds the strings of the profile&#39;s <code>leak</code> list and the names of your research tree. A hit refuses the push. A push to another branch runs no check in the hook, and CI runs gitleaks on it.</p><p>Run the check yourself before a commit, too:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> leaks</span></span></code></pre></div><p>It searches every tracked file, its path and the templates rendered with the example profile. Change the text that holds a hit. <a href="./development#the-pre-push-hook">development.md</a> describes both checks.</p><h2 id="the-verbs-for-the-whole-research-tree" tabindex="-1">The verbs for the whole research tree <a class="header-anchor" href="#the-verbs-for-the-whole-research-tree" aria-label="Permalink to &quot;The verbs for the whole research tree&quot;">​</a></h2><p>Five verbs act on every repository of the research tree. The research tree is the directory <code>$RESEARCH_ROOT</code>, else <code>~/Research</code>. Each verb is a dry run first, and <code>--apply</code> makes the change.</p><table tabindex="0"><thead><tr><th style="text-align:left;">verb</th><th style="text-align:left;">what it does</th></tr></thead><tbody><tr><td style="text-align:left;"><code>githooks</code></td><td style="text-align:left;">copies the shared git hooks of <code>githooks/</code> into <code>.githooks/</code> of each git repository directly below <code>Packages/</code> and <code>Experiments/</code>, and sets <code>core.hooksPath</code> there</td></tr><tr><td style="text-align:left;"><code>workflows</code></td><td style="text-align:left;">copies the canonical files of <code>githooks/workflows/</code> into each git repository directly below <code>Packages/</code> and <code>Experiments/</code> that has a <code>Project.toml</code>: the CI workflow, <code>dependabot.yml</code> and <code>codecov.yml</code> into each, and the TagBot workflow into each package. It copies the documentation workflow only where a tracked <code>docs/make.jl</code> exists, and never into a repository that the profile key <code>docs_exceptions</code> or <code>docs_additions</code> names. It deletes the retired <code>CompatHelper.yml</code></td></tr><tr><td style="text-align:left;"><code>trust</code></td><td style="text-align:left;">marks the research tree and each git repository below it as trusted in Claude Code&#39;s <code>~/.claude.json</code></td></tr><tr><td style="text-align:left;"><code>push-all</code></td><td style="text-align:left;">pushes each git repository directly below <code>Packages/</code> and <code>Experiments/</code> whose branch is ahead of its upstream, one at a time. It skips a repository with no upstream, one that is also behind its upstream, and one on a branch that is not the default branch, unless you give <code>--include-topic-branches</code></td></tr><tr><td style="text-align:left;"><code>format</code></td><td style="text-align:left;">runs JuliaFormatter over each tracked <code>.jl</code> file of the repositories below <code>Packages/</code> and <code>Experiments/</code>; it skips a repository that has no <code>.JuliaFormatter.toml</code></td></tr></tbody></table><p>Run each one in your own terminal, not from a session. The settings refuse a session&#39;s write to <code>.git/config</code> and to <code>~/.claude.json</code>. A <code>githooks</code> run that cannot set <code>core.hooksPath</code> prints the command for each repository. <code>push-all</code> runs the pre-push hook of each repository, and a hook that runs a full test suite can take a long time.</p><p>The copies of <code>githooks</code> and <code>workflows</code> are tracked files in each repository. Read the difference, then commit each copied file by name.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> githooks</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> githooks</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workflows</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> trust</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push-all</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> format</span></span></code></pre></div><h2 id="the-triggering-test-of-the-skills" tabindex="-1">The triggering test of the skills <a class="header-anchor" href="#the-triggering-test-of-the-skills" aria-label="Permalink to &quot;The triggering test of the skills&quot;">​</a></h2><p><code>harness skill-triggers</code> tests whether each skill loads on the queries that must load it, and stays unloaded on its near misses. The queries are in <code>tests/skill-triggers/&lt;skill&gt;.toml</code>. The dry run prints the number of queries per skill and the number of sessions that an <code>--apply</code> starts:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skill-triggers</span></span></code></pre></div><p><code>--apply --model &lt;alias&gt;</code> runs each query as one <code>claude -p</code> session on that model. Each session costs tokens, which you pay. <code>--skill &lt;name&gt;</code> limits the test to one skill, and it can repeat:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skill-triggers</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plan-parts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sonnet</span></span></code></pre></div><p>The result goes to <code>.scratch/skill-triggers/</code> in the research tree. Run the test after you change the <code>description</code> of a skill.</p>`,36)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
